import axios, { AxiosInstance, AxiosResponse } from 'axios';

const baseURL = process.env.REACT_APP_API_URL || '';

export type ApiResponse<T = any> = {
  isSuccess: boolean;
  data: T | null;
  errorMessage: string | null;
};

const apiHelper: AxiosInstance = axios.create({
  baseURL: baseURL,
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 15000,
});

export async function get<T = any>(url: string, params?: Record<string, any>): Promise<ApiResponse<T>> {
  try {
    const res = await apiHelper.get<T>(prepareUrl(url), { params });
    const d = res.data as ApiResponse<T>;
    return d;
  } catch (err) {
    return normalizeError(err);
  }
}

export async function post<T = any, U = any>(url: string, body?: U): Promise<ApiResponse<T>> {
  try {
    const res = await apiHelper.post<T>(prepareUrl(url), body);
   const d = res.data as ApiResponse<T>;
    return d;
  } catch (err) {
    return normalizeError(err);
  }
}

export function prepareUrl(path: string) {
  return `${baseURL}/${path}`;
}

export function setAuthToken(token: string | null) {
  if (token) {
    apiHelper.defaults.headers.common.Authorization = `Bearer ${token}`;
  } else {
    delete apiHelper.defaults.headers.common.Authorization;
  }
}

function normalizeError(error: any): ApiResponse<any> {
  if (error?.response) {
    const { data } = error.response as AxiosResponse;
    const message = (data && (data.message || data.error || data.errorMessage)) || 'Error';
    return { isSuccess: false, data: null, errorMessage: message };
  }
  return { isSuccess: false, data: null, errorMessage: error?.message || 'Network Error' };
}

export function setEnumUrl(enumObj: any) {
  return `${baseURL}/${enumObj}`;
}

export default apiHelper;