import React, { useEffect } from 'react';
import { Calendar, dateFnsLocalizer } from 'react-big-calendar';
import { format, parse, startOfWeek, getDay } from 'date-fns';
import { tr } from "date-fns/locale/tr";
import { SelectedDateModel } from '../../components/Big-Calendar/SelectedDateModel';
import AddWorkoutModal from './WorkoutAddModal/AddWorkoutModal';

import '../../components/Big-Calendar/big-calendar-custom.css';
import { EventModel } from '../../components/Big-Calendar/EventModel';
import { Workout } from '../Workout/WorkoutViewModal';
import { ApiResponse, post } from '../../helpers/apiHelper';
import { toastError } from '../../helpers/toast';
import { ConvertWorkoutToEvent } from '../../helpers/calendarHelper';
import Loading from '../../components/Layout/Loading';
import { useSelector } from 'react-redux';
import { RootState } from '../../store';

const locales = { tr };
const localizer = dateFnsLocalizer({
  format,
  parse,
  startOfWeek,
  getDay,
  locales,
});

const Home: React.FC = () => {
  const [date, setDate] = React.useState(new Date());
  const [isModalOpen, setIsModalOpen] = React.useState(false);
  const [selectedDate, setSelectedDate] = React.useState<Date | null>(null);
  const [selectedEvent, setSelectedEvent] = React.useState<EventModel[]>([]);
  const [workouts, setWorkouts] = React.useState<Workout[]>([]);
  const [workoutData, setWorkoutData] = React.useState<Workout[]>([]);
  const [loading, setLoading] = React.useState<boolean>(false);
  const [events, setEvents] = React.useState<EventModel[]>([]);
  const userId = useSelector((s: RootState) => s.auth.id);

  const refreshData = async () => {
    await fetchWorkouts();
    await fetchWorkoutData();
  };
  useEffect(() => {
    setEvents(ConvertWorkoutToEvent(workoutData));
  }, [workoutData]);
  useEffect(() => {
    fetchWorkouts();
    fetchWorkoutData();
    setEvents(ConvertWorkoutToEvent(workoutData));
  }, []);

  const fetchWorkouts = async () => {
    setLoading(true);
    try {
      const res = await post<ApiResponse<Workout[]>>('getworkouts.php');
      if (res && res.isSuccess && Array.isArray(res.data)) {
        setWorkouts(res.data);
      } else {
        setWorkouts([]);
        toastError(res?.errorMessage || 'Workout Alamadık');
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchWorkoutData = async () => {
    setLoading(true);
    try {
      const res = await post<ApiResponse<Workout[]>>('getworkoutdata.php', { UserId: userId });
      if (res && res.isSuccess && Array.isArray(res.data)) {
        setWorkoutData(res.data);
      } else {
        setWorkoutData([]);
        toastError(res?.errorMessage || 'Workout Alamadık');
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }
  const onSelectSlot = (slotInfo: SelectedDateModel) => {
    if (loading) return;

    if (slotInfo.action === "doubleClick") {
      setSelectedDate(slotInfo.start);
      setSelectedEvent([]);
      setIsModalOpen(true);
    }
  }

  const onSelectEvent = (event: any) => {
    if (loading) return;

    setSelectedDate(event.start);
    setSelectedEvent([event]);
    setIsModalOpen(true);
  };

  return (
    <main>
      <h1>Takvim</h1>
      <p>Planlama için boş olan günlere 2 kere tıkla</p>
      <Calendar
        localizer={localizer}
        events={events}
        startAccessor="start"
        endAccessor="end"
        style={{ height: '100vh' }}
        views={['month']}
        defaultView="month"
        onNavigate={setDate}
        date={date}
        selectable={true}
        onSelectSlot={onSelectSlot}
        onSelectEvent={onSelectEvent}
      />

      <AddWorkoutModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        date={selectedDate}
        events={selectedEvent}
        workouts={workouts}
        onAdded={refreshData}
      />

      {loading && <Loading />}
    </main>
  );
};

export default Home;
