import React, { useState } from "react";
import { Exercise } from './ExerciseModel';
import { post, ApiResponse } from '../../../helpers/apiHelper';
import { toastSuccess, toastError } from '../../../helpers/toast';

interface ExerciseAddProps {
    onAdded?: () => void;
    loading: boolean;
}

const ExerciseAddComponent: React.FC<ExerciseAddProps> = ({
    onAdded,
    loading,
}) => {
    const [workoutname, setWorkoutname] = useState<string>("");
    const [workoutdescription, setWorkoutdescription] = useState<string>("");
    const [isCardio, setIsCardio] = useState<boolean>(false);
    const [inserting, setInserting] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const exercise: Exercise = {
            Id: null,
            Name: workoutname,
            Description: workoutdescription,
            IsCardio: isCardio,
        };

        setInserting(true);
        try {
            const result: ApiResponse<null> = await post('addexercise.php', exercise);
            if (result.isSuccess === true) {
                toastSuccess('Egzersiz Eklendi');
                setWorkoutdescription("");
                setWorkoutname("");
                setIsCardio(false);
               if(onAdded) onAdded();
            } else {
                const msg = result.errorMessage || 'Yükleyemedim';
                toastError(msg);
            }
        } catch (err: any) {
            const msg = err?.data?.message || err?.message || 'Login failed';
            toastError(msg);
        } finally {
            setInserting(false);
        }
    };


    return (
        <div className="exercise-form-container">
            <h2>Hareket Ekle</h2>

            <form onSubmit={(e) => e.preventDefault()} className="exercise-form">
                <label>
                    Hareket İsmi
                    <input
                        type="text"
                        value={workoutname}
                        onChange={(e) => setWorkoutname(e.target.value)}
                        required
                    />
                </label>

                <label>
                    Açıklama
                    <textarea
                        value={workoutdescription}
                        onChange={(e) => setWorkoutdescription(e.target.value)}
                        rows={4}
                    />
                </label>

                <label className="checkbox-label">
                    <input
                        type="checkbox"
                        checked={isCardio}
                        onChange={(e) => setIsCardio(e.target.checked)}
                    />
                    Kardiyomu?
                </label>

                <button
                    type="button"
                    onClick={handleSubmit}
                    className="btn-primary"
                    disabled={loading}
                >
                    {inserting ? "Hareketi Ekliyorum..." : "Hareketi Ekle"}
                </button>
            </form>
        </div>
    );
};

export default ExerciseAddComponent;
