import { Workout } from "../pages/Workout/WorkoutViewModal"
import { EventModel, EventWorkoutModel } from "../components/Big-Calendar/EventModel";

export const ConvertWorkoutToEvent = (workouts: Workout[] | null) => {
    let calendarEvent: EventModel[] = [];
    workouts?.forEach((workout) => {
        const workoutModel : EventWorkoutModel ={
            exercises : workout.Exercises,
            name : workout.WorkoutName,
            id : workout.Id
        }

        const event: EventModel = {
            title: workout.WorkoutName,
            start: new Date(workout.Date),
            end: new Date(workout.Date),
            resources: workoutModel
        };
        calendarEvent.push(event);
    }); 
    return calendarEvent;
};

export const IsEventToday = (event: EventModel): boolean => {
    const today = new Date();
    const eventDate = new Date(event.start);
    return today.toDateString() === eventDate.toDateString();
}

export const IsDatePast = (date: Date): boolean => {
    const yesterday = new Date();
    yesterday.setDate(new Date().getDate() - 1);
    return date < yesterday;
}
export default { ConvertWorkoutToEvent, IsEventToday, IsDatePast };