import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import UserModel from '../helpers/user';

interface AuthState {
  user: string | null;
  isAdmin?: boolean | null;
  id:number | null;
}

const COOKIE_NAME = 'wp_user';

function getCookie(name: string): string | null {
  try {
    const match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
    if (!match) return null;
    return decodeURIComponent(match[2]);
  } catch (e) {
    return null;
  }
}

function setCookie(name: string, value: string, days = 7) {
  try {
    const maxAge = days ? `; Max-Age=${days * 24 * 60 * 60}` : '';
    const isSecure = typeof window !== 'undefined' && window.location && window.location.protocol === 'https:';
    const secure = isSecure ? '; Secure' : '';
    const sameSite = '; SameSite=Lax';
    document.cookie = `${name}=${encodeURIComponent(value)}${maxAge}; Path=/${sameSite}${secure}`;
  } catch (e) {
    // ignore
  }
}

function removeCookie(name: string) {
  try {
    document.cookie = `${name}=; Max-Age=0; Path=/; SameSite=Lax`;
  } catch (e) {
    // ignore
  }
}

function loadInitialUser(): AuthState | null {
  try {
    const raw = getCookie(COOKIE_NAME);
    if (!raw) return null;
    return JSON.parse(raw) as AuthState | null;
  } catch (e) { 
    return null;
  }
}

const initialState: AuthState = loadInitialUser() || {
  user: null,
  isAdmin: null,
  id: null,
};

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    setUser(state, action: PayloadAction<UserModel | null>) {
      state.isAdmin = action.payload?.IsAdmin;
      state.user = action.payload ? action.payload.Username : null;
      state.id = action.payload ? action.payload.Id : null;
      const cookieValue : AuthState ={user : state.user, isAdmin: state.isAdmin, id: state.id};
      try {
        if (action.payload) setCookie(COOKIE_NAME, JSON.stringify(cookieValue), 7);
        else removeCookie(COOKIE_NAME);
      } catch (e) {
        // ignore
      }
    },
    clearUser(state) {
      state.user = null;
      try {
        removeCookie(COOKIE_NAME);
      } catch (e) {
        // ignore
      }
    },
  },
});

export const { setUser, clearUser } = authSlice.actions;
export default authSlice.reducer;