import React, { useState } from "react";
import "./AddWorkoutModal.css";
import { EventModel } from "../../../components/Big-Calendar/EventModel";
import { Workout } from "../../Workout/WorkoutViewModal";
import { useSelector } from "react-redux";
import { RootState } from "../../../store";
import { ApiResponse, post } from "../../../helpers/apiHelper";
import AddWorkoutDataModel from "./AddWorkoutDataModel";
import { toastSuccess } from "../../../helpers/toast";
import { IsDatePast, IsEventToday } from "../../../helpers/calendarHelper";
import { useNavigate } from "react-router-dom";

interface AddWorkoutModalProps {
  isOpen: boolean;
  onClose: () => void;
  date?: Date | null;
  events: EventModel[];
  workouts?: Workout[];
  onAdded: () => void;
}


const CustomModal: React.FC<AddWorkoutModalProps> = ({ isOpen, onClose, date, events, workouts, onAdded }) => {
  const navigate = useNavigate();

  const [selectedWorkoutId, setSelectedWorkoutId] = useState<string | null>(null);
  const userId = useSelector((s: RootState) => s.auth.id);
  const addWorkoutData = async (selectedWorkout: number, date: Date) => {
    const payload: AddWorkoutDataModel = {
      UserId: userId ? userId : 0,
      WorkoutId: selectedWorkout,
      Date: date.getFullYear() + "-" +
        String(date.getMonth() + 1).padStart(2, '0') + "-" +
        String(date.getDate()).padStart(2, '0') + " " +
        String(date.getHours()).padStart(2, '0') + ":" +
        String(date.getMinutes()).padStart(2, '0') + ":" +
        String(date.getSeconds()).padStart(2, '0')
    };
    const response = await post<ApiResponse<null>>('addworkoutdata.php', payload);
    if (response.isSuccess) {
      toastSuccess('Workout Data başarıyla eklendi');
      onAdded();
      onClose();
    }
  };

  if (!isOpen) return null;

  return (
    <div className="modal-backdrop">
      <div className="modal-content">
        <h2>Seçilen Tarih</h2>
        <p>{date?.toLocaleDateString()}</p>
        {events.length == 0 && !IsDatePast(date!) && (
          <>
            <label>Workout Seç:</label>
            <select className="workout-dropdown"
              value={selectedWorkoutId ?? ""}
              onChange={(e) => setSelectedWorkoutId(e.target.value)}
            >
              <option value="">Seçiniz...</option>
              {workouts?.map((w) => (
                <option key={w.Id} value={w.Id}>
                  {w.WorkoutName}
                </option>
              ))}
            </select>
            <button
              disabled={!selectedWorkoutId}
              onClick={() => addWorkoutData(Number(selectedWorkoutId), date!)}>
              Ekle
            </button>
          </>
        )}
        {events.length !== 0 && (
          <>
            {events?.map((ev) => (
              <>
                <p key={ev.resources.id}>{ev.resources.name}</p>
                {IsEventToday(ev) && (
                  <button onClick={() => navigate(`/activity/${ev.resources.id}/${ date!.getFullYear() + "-" +
                    String(date!.getMonth() + 1).padStart(2, '0') + "-" +
                    String(date!.getDate()).padStart(2, '0') + " " +
                    String(date!.getHours()).padStart(2, '0') + ":" +
                    String(date!.getMinutes()).padStart(2, '0') + ":" +
                    String(date!.getSeconds()).padStart(2, '0')}`)}>
                    Başla
                  </button>)}
                {IsDatePast(ev.start) && <button>Geçmiş Etkinlik</button>}
              </>
            ))}
          </>
        )}
        <button onClick={onClose}>Kapat</button>
      </div>
    </div>
  );
};

export default CustomModal;