import React, { useEffect, useState } from 'react';
import { Workout } from './WorkoutViewModal';
import './Workouts.css';
import Loading from '../../components/Layout/Loading';
import { ApiResponse, post } from '../../helpers/apiHelper';
import { toastError } from '../../helpers/toast';

const Workouts: React.FC = () => {
  const [workouts, setWorkouts] = useState<Workout[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [expandedWorkout, setExpandedWorkout] = useState<number | null>(null);

  useEffect(() => {
    fetchWorkouts();
  }, []);

  const fetchWorkouts = async () => {
    setLoading(true);
    try {
      const res = await post<ApiResponse<Workout[]>>('getworkouts.php');
      if (res && res.isSuccess && Array.isArray(res.data)) {
        setWorkouts(res.data);
      } else {
        setWorkouts([]);
        toastError(res?.errorMessage || 'Workout Alamadık');
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const toggleWorkout = (id: number) => {
    setExpandedWorkout(expandedWorkout === id ? null : id);
  };

  return (
    <main>
      <h1>Workouts</h1>
      {loading && (
        <Loading />
      )}

      {workouts.map((workout) => (
        <div key={workout.Id} className="workout-item">
          <div
            className="workout-header"
            onClick={() => toggleWorkout(workout.Id)}
          >
            {workout.WorkoutName}
          </div>
          {expandedWorkout === workout.Id && (
            <ul className="exercise-list">
              {workout.Exercises.map((ex) => (
                <li key={ex.Id}>{ex.ExerciseName}</li>
              ))}
            </ul>
          )}
        </div>
      ))}
    </main>
  );
};

export default Workouts;