import React, { useState, useEffect, use } from "react";
import { Exercise } from './ExerciseModel';
import './AddExercise.css';
import { get, post, ApiResponse } from '../../../helpers/apiHelper';
import { toastSuccess, toastError } from '../../../helpers/toast';
import ExercisesTable from "./ExercisesTable";
import GenericModal from "../GenericModal";
import { useExercises } from "./ExerciseApiHooks";
import ExerciseAddComponent from "./ExerciseAddComponent";
import Loading from "../../../components/Layout/Loading";

const AddExercise: React.FC = () => {
  const {
    deleteId,
    updateItem,
    openDeleteModal,
    closeDeleteModal,
    handleDelete,
    handleUpdate,
    openUpdateModal,
    closeUpdateModal,
    setUpdateItem,
  } = useExercises();


  const [loading, setLoading] = useState(false);
  const [exercises, setExercises] = useState<Exercise[]>([]);
  const [exerciseTrigger, setExerciseTrigger] = useState<boolean>(false);

  useEffect(() => {
    const fetchExercises = async () => {
      setLoading(true);
      try {
        const result: ApiResponse<Exercise[]> = await get('getexercises.php');
        if (result.isSuccess === true) {
          setExercises(result.data || []);
        } else {
          const msg = result.errorMessage || 'Hareketleri Yükleyemedim';
          toastError(msg);
        }
      } catch (err: any) {
        const msg = err?.data?.message || err?.message || 'Hareketleri Yükleyemedim';
        toastError(msg);
      } finally {
        setLoading(false);
      }
    }
    fetchExercises();
  }, [, exerciseTrigger]);

  return (
    <main>
      {loading && <Loading/>}
      <ExerciseAddComponent
        loading={loading}
        onAdded={() => setExerciseTrigger(!exerciseTrigger)}
      />

      <ExercisesTable
        exercises={exercises}
        onDelete={openDeleteModal}
        onUpdate={openUpdateModal}
      />

      <GenericModal
        isOpen={deleteId !== null}
        onClose={() => closeDeleteModal()}
        title="Silme Onayı"
        actions={
          <>
            <button className="delete-btn" onClick={async () => {
              await handleDelete();
              setExerciseTrigger(t => !t);
            }}>Evet, Sil</button>
            <button onClick={closeDeleteModal}>İptal</button>
          </>
        }
      >
        <p>Bu hareketi silmek istediğinize emin misiniz?</p>
      </GenericModal>

      <GenericModal
        isOpen={updateItem !== null}
        onClose={closeUpdateModal}
        title="Egzersiz Güncelle"
        actions={
          <>
            <button className="update-btn" onClick={async () => {
              await handleUpdate();
              setExerciseTrigger(t => !t);
            }}>Kaydet</button>
            <button onClick={closeUpdateModal}>İptal</button>
          </>
        }
      >
        {updateItem && (
          <div>
            <label>Adı</label>
            <input
              type="text"
              value={updateItem.Name}
              onChange={e => setUpdateItem({ ...updateItem, Name: e.target.value })}
            />

            <label>Açıklama</label>
            <textarea
              value={updateItem.Description}
              onChange={e => setUpdateItem({ ...updateItem, Description: e.target.value })}
            />

            <label>
              <input
                type="checkbox"
                checked={updateItem.IsCardio}
                onChange={e => setUpdateItem({ ...updateItem, IsCardio: e.target.checked })}
              />
              Kardiyo mu?
            </label>
          </div>
        )}
      </GenericModal>

    </main>
  );
}
export default AddExercise;