import { useState, useCallback } from "react";
import { get, post, ApiResponse } from '../../../helpers/apiHelper';
import { Exercise } from '../AddExercise/ExerciseModel';
import { toastSuccess, toastError } from '../../../helpers/toast';
import { Workout } from "./WorkoutModel";

export const useWorkoutApi = () => {
  const [exercises, setExercises] = useState<Exercise[]>([]);
  const [loading, setLoading] = useState(false);

  interface WorkoutPayload {
    WorkoutName: string;
    Items: Workout[];
  }

  const fetchExercises = useCallback(async () => {
    setLoading(true);
    try {
      const result: ApiResponse<Exercise[]> = await get('getexercises.php');
      if (result.isSuccess) {
        setExercises(result.data || []);
      } else {
        toastError(result.errorMessage || 'Hareketleri yükleyemedim');
      }
    } catch (err: any) {
      const msg = err?.data?.message || err?.message || 'Hareketleri yükleyemedim';
      toastError(msg);
    } finally {
      setLoading(false);
    }
  }, []);

  const addWorkout = useCallback(async (WorkoutName: string ,Items: Workout[]) => {
    setLoading(true);
    try {
      const newPayload: WorkoutPayload = { WorkoutName, Items };
      const result: ApiResponse<null> = await post('addworkout.php', newPayload);
      if (result.isSuccess) {
        toastSuccess('Workout kaydedildi');
        return true;
      } else {
        toastError(result.errorMessage || 'Workout kaydedilemedi');
        return false;
      }
    } catch (err: any) {
      const msg = err?.data?.message || err?.message || 'Workout kaydedilemedi';
      toastError(msg);
      return false;
    } finally {
      setLoading(false);
    }
  }, []);

  return {
    exercises,
    loading,
    fetchExercises,
    addWorkout
  };
};