import React, { useEffect } from 'react';
import './App.css';
import { Navigate, useLocation, useNavigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import type { RootState } from './store';
import Layout from './components/Layout/Layout';
import Home from './pages/Calendar/Home';
import Workouts from './pages/Workout/Workouts';
import Graphics from './pages/Graphs/Graphics';
import Login from './pages/Login/Login';
import AddExercise from './pages/Admin/AddExercise/AddExercise';
import AddWorkout from './pages/Admin/AddWorkout/AddWorkout';
import Activity from './pages/Activity/Activity';

function App() {
  const user = useSelector((s: RootState) => s.auth.user);
  const IsLoggedIn = () => user && user.length > 0;
  const navigate = useNavigate();
  const location = useLocation();
  const path = location.pathname || '/';

  useEffect(() => {
    if (!IsLoggedIn() && path !== '/login') {
      navigate('/login', { replace: true });
      return;
    }

    if (IsLoggedIn() && path === '/login') {
      navigate('/', { replace: true });
    }
  }, [user, path, navigate]);

  if (!IsLoggedIn()) {
    return <Login />;
  }

  if (path.startsWith('/workouts')) {
    return (
      <Layout>
        <Workouts />
      </Layout>
    );
  }

  if (path.startsWith('/graphics')) {
    return (
      <Layout>
        <Graphics />
      </Layout>
    );
  }
  if (path.startsWith('/addexercise')) {
    return (
      <Layout>
        <AddExercise />
      </Layout>
    );
  }

  if (path.startsWith('/activity')) {
    return (
      <Layout>
        <Activity />
      </Layout>
    );
  }

  if (path.startsWith('/addworkout')) {
    return (
      <Layout>
        <AddWorkout />
      </Layout>
    );
  }

  return (
    <Layout>
      <Home />
    </Layout>
  );
}

export default App;