import React, { useState } from 'react';
import { NavLink } from 'react-router-dom';
import './NavBar.css';
import { useSelector, useDispatch } from 'react-redux';
import type { RootState } from '../../store';
import { clearUser } from '../../store/authSlice';
import "./Pages.css";

const NavBar: React.FC = () => {
  const [open, setOpen] = useState(false);
  const user = useSelector((s: RootState) => s.auth.user);
  const isAdmin = useSelector((s: RootState) => s.auth.isAdmin);
  const dispatch = useDispatch();

  const close = () => setOpen(false);

  return (
    <header className="nav-header">
      <div className="nav-inner">
        <div className="nav-brand">Basmaya Hoşgeldin Kardeş {user}</div>
        <button
          className={`nav-toggle ${open ? 'open' : ''}`}
          aria-label="Toggle navigation"
          aria-expanded={open}
          onClick={() => setOpen((s) => !s)}
        >
          <span />
          <span />
          <span />
        </button>

        <nav className={`nav-links ${open ? 'open' : ''}`} onClick={close}>
          <NavLink to="/" className={({ isActive }) => (isActive ? 'active' : '')} end>
            Home
          </NavLink>
          <NavLink to="/workouts" className={({ isActive }) => (isActive ? 'active' : '')}>
            Workouts
          </NavLink>
          <NavLink to="/graphics" className={({ isActive }) => (isActive ? 'active' : '')}>
            Graphics
          </NavLink>
          {isAdmin && (
            <>
              <NavLink to="/addexercise" className={({ isActive }) => (isActive ? 'active adminButton' : 'adminButton')}>
                Haraket CRUD
              </NavLink>

              <NavLink to="/addworkout" className={({ isActive }) => (isActive ? 'active adminButton' : 'adminButton  ')}>
                Antrenman Programı Ekle
              </NavLink>
            </>
          )}

        </nav>
        <button
          className="logout-btn"
          onClick={() => dispatch(clearUser())}
          aria-label="Logout"
          title="Logout">
          Çıkış Yap
        </button>
      </div>
    </header>
  );
};

export default NavBar;
