import { useState } from "react";
import { post, ApiResponse } from '../../../helpers/apiHelper';
import { toastSuccess, toastError } from '../../../helpers/toast';
import { Exercise } from "./ExerciseModel";

export function useExercises() {
  const [loading, setLoading] = useState(false);

  const [deleteId, setDeleteId] = useState<number | null>(null);
  const openDeleteModal = (id: number | null) => setDeleteId(id);
  const closeDeleteModal = () => setDeleteId(null);

  const [updateItem, setUpdateItem] = useState<Exercise | null>(null);
  const openUpdateModal = (exercise: Exercise | null) => setUpdateItem(exercise);
  const closeUpdateModal = () => setUpdateItem(null);

  const handleDelete = async () => {
    if (!deleteId) return;
    setLoading(true);
    try {
      const result: ApiResponse<null> = await post('deleteexercise.php', { deleteId: deleteId });
      if (result.isSuccess === true) {
        toastSuccess('Egzersiz Silindi');
      } else {
        const msg = result.errorMessage || 'Silinemedi';
        toastError(msg);
      }
    } catch (err: any) {
      const msg = err?.data?.message || err?.message || 'API de hata oluştu';
      toastError(msg);
    } finally {
      setLoading(false);
      closeDeleteModal();
    }
  };


  const handleUpdate = async () => {
    if (!updateItem) return;

    try {
      const result = await post('updateexercise.php', updateItem);

      if (result.isSuccess) {
        toastSuccess("Güncellendi");
        closeUpdateModal();
      } else {
        toastError(result.errorMessage || "Güncellenemedi");
      }
    } catch (e: any) {
      toastError(e?.message || "API hatası");
    }
  };

  return {
    deleteId,
    updateItem,
    openDeleteModal,
    closeDeleteModal,
    handleDelete,
    handleUpdate,
    openUpdateModal,
    closeUpdateModal,
    setUpdateItem,
  };
}