import React, { useState } from 'react';
import './Login.css';
import { useDispatch } from 'react-redux';
import { setUser } from '../../store/authSlice';
import { Gifs } from '../../consts/Gifs';
import { setEnumUrl, post, ApiResponse } from '../../helpers/apiHelper';
import { toastSuccess, toastError } from '../../helpers/toast';
import { useNavigate } from 'react-router-dom';
import UserModel from '../../helpers/user';

const Login: React.FC = () => {
  const dispatch = useDispatch();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const submit = async (e: React.FormEvent) => {
  e.preventDefault();
  if (!username || !password) {
    toastError('Please enter username and password');
    return;
  }

  setLoading(true);
  try {
    const result: ApiResponse<UserModel> = await post('login.php', { Username: username, Password: password });
    if (result.isSuccess === true && result.data) {
      if(result.data.RoleId === 1){
        result.data.IsAdmin = true;
      }
      dispatch(setUser(result.data || null));
      toastSuccess('Ojgeldin Beaa');
      navigate('/', { replace: true });
    } else {
      const msg = result.errorMessage || 'Login failed';
      toastError(msg);
    }
  } catch (err: any) {
    const msg = err?.data?.message || err?.message || 'Login failed';
    toastError(msg);
  } finally {
    setLoading(false);
  }
};

  return (
    <div className="login-page">
      <div className="login-panel">
        <div className="login-visual">
          <img
            src={setEnumUrl(Gifs.LoginGif )}
            alt="Workout"
          />
        </div>
        <div className="login-form-wrap">
          <h2>Giriş Yap</h2>
          <p className="muted">Karşim Basmaya mı Geldin?? </p>
          <form className="login-form" onSubmit={submit}>
            <label className="field">
              <span className="label">Rumuz</span>
              <input
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                required
              />
            </label>

            <label className="field">
              <span className="label">Parola</span>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </label>

            <div className="actions">
              <button type="submit" className="btn-primary" disabled={loading}>
                {loading ? 'Giriş Yapılıyor…' : 'Giriş Yap'}
              </button>
            </div>
          </form>

          <div className="login-foot muted">Hesabın yokmu? O zaman git burdan.</div>
        </div>
      </div>
    </div>
  );
};

export default Login;
