import React, { useEffect, useState } from "react";
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";
import { ApiResponse, get } from "../../helpers/apiHelper";
import { RootState } from "../../store";
import { useSelector } from "react-redux";

interface WorkoutSet {
  Workout_Data_Id: number;
  Workout_Id: number;
  Workout_Name: string;
  Exercise_Id: number;
  Exercise_Name: string;
  Weight: number | null;
  Minute: number | null;
  IsCardio: boolean;
  Date: string;
}

const COLORS = [
  "#8884d8",
  "#82ca9d",
  "#ffc658",
  "#ff8042",
  "#8dd1e1",
  "#a4de6c",
  "#d0ed57",
  "#ffc0cb",
];

const WorkoutGraphicsPage: React.FC = () => {
  const [workoutSets, setWorkoutSets] = useState<WorkoutSet[]>([]);
  const [loading, setLoading] = useState(false);
  const userId = useSelector((s: RootState) => s.auth.id);
  
  useEffect(() => {
    const fetchWorkoutSets = async () => {
      setLoading(true);
      try {
        const res: ApiResponse<WorkoutSet[]> = await get(`getsetdata.php?userId=${userId}`);
        if (res.isSuccess && res.data) {
          setWorkoutSets(res.data);
        } else {
          setWorkoutSets([]);
        }
      } catch (err: any) {
        setWorkoutSets([]);
      } finally {
        setLoading(false);
      }
    };
    fetchWorkoutSets();
  }, []);

  if (loading) return <div>Loading...</div>;
  if (!workoutSets.length) return <div>No workout data available.</div>;

  // Workout bazında grupla
  const workouts = Array.from(new Set(workoutSets.map((s) => s.Workout_Name)));

  return (
    <div className="p-4 space-y-12">
      {workouts.map((workoutName, idx) => {
        const sets = workoutSets.filter((s) => s.Workout_Name === workoutName);

        // Weight (non-cardio) ve Cardio ayrı ayrı filtrele
        const weightSets = sets.filter((s) => !s.IsCardio);
        const cardioSets = sets.filter((s) => s.IsCardio);

        // ======== WEIGHT CHART DATA ========
        const weightExercises = Array.from(new Set(weightSets.map((s) => s.Exercise_Name)));
        const weightDataByDate: { [date: string]: any } = {};

        weightSets.forEach((s) => {
          if (!weightDataByDate[s.Date]) weightDataByDate[s.Date] = { Date: s.Date };
          if (!weightDataByDate[s.Date][s.Exercise_Name]) {
            weightDataByDate[s.Date][s.Exercise_Name] = { total: s.Weight ?? 0, count: 1 };
          } else {
            weightDataByDate[s.Date][s.Exercise_Name].total += s.Weight ?? 0;
            weightDataByDate[s.Date][s.Exercise_Name].count += 1;
          }
        });

        const weightChartData = Object.values(weightDataByDate)
          .map((d: any) => {
            const final: any = { Date: d.Date };
            weightExercises.forEach((ex) => {
              final[ex] = d[ex] ? d[ex].total / d[ex].count : null;
            });
            return final;
          })
          .sort((a, b) => new Date(a.Date).getTime() - new Date(b.Date).getTime());

        // ======== CARDIO CHART DATA ========
        const cardioExercises = Array.from(new Set(cardioSets.map((s) => s.Exercise_Name)));
        const cardioDataByDate: { [date: string]: any } = {};

        cardioSets.forEach((s) => {
          if (!cardioDataByDate[s.Date]) cardioDataByDate[s.Date] = { Date: s.Date };
          if (!cardioDataByDate[s.Date][s.Exercise_Name]) {
            cardioDataByDate[s.Date][s.Exercise_Name] = { total: s.Minute ?? 0, count: 1 };
          } else {
            cardioDataByDate[s.Date][s.Exercise_Name].total += s.Minute ?? 0;
            cardioDataByDate[s.Date][s.Exercise_Name].count += 1;
          }
        });

        const cardioChartData = Object.values(cardioDataByDate)
          .map((d: any) => {
            const final: any = { Date: d.Date };
            cardioExercises.forEach((ex) => {
              final[ex] = d[ex] ? d[ex].total / d[ex].count : null;
            });
            return final;
          })
          .sort((a, b) => new Date(a.Date).getTime() - new Date(b.Date).getTime());

        return (
          <div key={idx} className="border p-4 rounded shadow space-y-8">
            <h2 className="text-xl font-bold">{workoutName} Workout</h2>

            {/* Weight Line Chart */}
            {weightChartData.length > 0 && (
              <div>
                <h3 className="text-lg font-semibold mb-2">Weight Progress</h3>
                <ResponsiveContainer width="100%" height={320}>
                  <LineChart data={weightChartData}>
                    <XAxis dataKey="Date" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    {weightExercises.map((ex, i) => (
                      <Line
                        key={ex}
                        dataKey={ex}
                        stroke={COLORS[i % COLORS.length]}
                        strokeWidth={2}
                        dot={{ r: 4 }}
                        connectNulls
                      />
                    ))}
                  </LineChart>
                </ResponsiveContainer>
              </div>
            )}

            {/* Cardio Bar Chart */}
            {cardioChartData.length > 0 && (
              <div>
                <h3 className="text-lg font-semibold mb-2 text-orange-600">Cardio Minutes</h3>
                <ResponsiveContainer width="100%" height={260}>
                  <BarChart data={cardioChartData}>
                    <XAxis dataKey="Date" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    {cardioExercises.map((ex, i) => (
                      <Bar
                        key={ex}
                        dataKey={ex}
                        fill={COLORS[i % COLORS.length]}
                      />
                    ))}
                  </BarChart>
                </ResponsiveContainer>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default WorkoutGraphicsPage;
