import { useCallback, useState } from "react";
import { Exercise } from "../Workout/WorkoutViewModal";
import { ApiResponse, post } from "../../helpers/apiHelper";
import { toastError } from "../../helpers/toast";

export const useActivityApiHooks = () => {
    const [exercises, setExercises] = useState<Exercise[]>([]);
    const [loading, setLoading] = useState(false);


    const fetchWorkoutExercises = useCallback(async (workoutId: number): Promise<Exercise[]> => {
        setLoading(true);
        try {
            const result: ApiResponse<Exercise[]> = await post('getworkoutexerices.php', { WorkoutId: workoutId });
            if (result.isSuccess) {
                setExercises(result.data || []);
                return result.data || [];
            } else {
                toastError(result.errorMessage || 'Hareketleri yükleyemedim');
                return [];
            }
        } catch (err: any) {
            const msg = err?.data?.message || err?.message || 'Hareketleri yükleyemedim';
            toastError(msg);
            return [];
        } finally {
            setLoading(false);
        }
    }, []);

    const getWorkoutDataId = useCallback(async (workoutId: number, userId: number, date: string): Promise<number> => {
        setLoading(true);

        try {
            const result: ApiResponse<number> = await post('checkworkoutvisibility.php', {
                WorkoutId: workoutId, UserId: userId,
                Date: date
            });
            if (result.isSuccess) {
                return result.data || 0;
            } else {
                return 0;
            }
        } catch {
            return 0;
        } finally {
            setLoading(false);
        }
    }, []);

    return {
        exercises,
        loading,
        fetchWorkoutExercises,
        getWorkoutDataId
    };
};
