import React from "react";
import { Exercise } from '../AddExercise/ExerciseModel';

interface ExercisesTableProps {
  exercises: Exercise[];
  onDelete: (id: number | null) => void;
  onUpdate: (exercise: Exercise | null) => void;
}

const ExercisesTable = ({ exercises, onDelete, onUpdate }: ExercisesTableProps) => {
  return (
    <table className="exercise-table">
      <thead>
        <tr>
          <th>Hareket</th>
          <th>Açıklama</th>
          <th>Tür</th>
          <th>Aksiyonlar</th>
        </tr>
      </thead>

      <tbody>
        {exercises.map((exercise, i) => (
          <tr key={i}>
            <td>{exercise.Name}</td>
            <td>{exercise.Description}</td>
            <td>{exercise.IsCardio ? "Kardiyo" : "Kuvvet"}</td>
            <td className="actions">
              <button
                className="update-btn"
                onClick={() => onUpdate(exercise)}
              >
                Güncelle
              </button>

              <button className="delete-btn" onClick={() => onDelete(exercise.Id)}>
                Sil
              </button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default ExercisesTable;
