import React, { useState, useEffect } from "react";
import WorkoutTable from "./WorkoutTable";
import { Workout } from "./WorkoutModel";
import { useWorkoutApi } from "./WorkoutApiHooks";
import { toastError } from "../../../helpers/toast";
import Loading from "../../../components/Layout/Loading";

const AddWorkout: React.FC = () => {
    const [workoutName, setWorkoutName] = useState<string>("");
    const [selectedList, setSelectedList] = useState<Workout[]>([
        { Id: Date.now(), ExerciseId: "", Weight: "", Set: "", Rep: "", Time: "" }
    ]);

    const { exercises, loading, fetchExercises, addWorkout } = useWorkoutApi();

    useEffect(() => {
        fetchExercises();
    }, [fetchExercises]);

    const handleChange = (id: number | null, field: string | "", value: string | null) => {
        if (field === "ExerciseId" && value === "") {
            removeItem(id ? id : 0);
            return;
        }

        setSelectedList((prev) =>
            prev.map((item) =>
                item.Id === id ? { ...item, [field]: value } : item
            )
        );

        setSelectedList((prev) => {
            const last = prev[prev.length - 1];
            if (last.Id === id && field === "ExerciseId" && value !== "") {
                return [
                    ...prev,
                    { Id: Date.now(), ExerciseId: "", Weight: "", Set: "", Rep: "", Time: "" }
                ];
            }
            return prev;
        });
    };

    const removeItem = (id: number) => {
        setSelectedList((prev) => prev.filter((item) => item.Id !== id));
    };

    const handleSave = async () => {
        if (!workoutName.trim()) {
            toastError("Workout Name boş olamaz!");
            return;
        }

        const filteredList = selectedList.filter(item => item.ExerciseId !== "");
        if (filteredList.length === 0) {
            toastError("En az bir hareket eklemelisiniz!");
            return;
        }
        await addWorkout(workoutName, filteredList);
    };

    return (
        <main>
            {loading && (
                <Loading />
            )}
            <div className="workout-name-container">
                <label>Workout Name</label>
                <input
                    type="text"
                    placeholder="Workout adı girin"
                    value={workoutName}
                    onChange={(e) => setWorkoutName(e.target.value)}
                />
            </div>

            <WorkoutTable
                selectedList={selectedList}
                exercises={exercises}
                handleChange={handleChange}
                removeItem={removeItem}
            />

            <div className="save-container">
                <button className="save-btn" onClick={handleSave}>
                    Kaydet
                </button>
            </div>
        </main>
    );
};

export default AddWorkout;
