import { toast } from 'react-toastify';

export const toastSuccess = (message: string) => {
  toast.success(message, { position: 'top-right', autoClose: 1000 });
};

export const toastError = (message: string) => {
  toast.error(message, { position: 'top-right', autoClose: 3000 });
};

export const toastInfo = (message: string) => {
  toast.info(message, { position: 'top-right', autoClose: 1000 });
};

export const toastWarn = (message: string) => {
  toast.warn(message, { position: 'top-right', autoClose: 1000 });
};

export default { toastSuccess, toastError, toastInfo, toastWarn };
