import React from "react";
import { Exercise } from '../AddExercise/ExerciseModel';
import { Workout } from "./WorkoutModel";
import './AddWorkout.css';


interface WorkoutTableProps {
    selectedList: Workout[];
    exercises: Exercise[];
    handleChange: (id: number | null, field: string | "", value: string | null) => void;
    removeItem: (id: number) => void;
}

const WorkoutTable: React.FC<WorkoutTableProps> = ({
    selectedList,
    exercises,
    handleChange,
    removeItem
}) => {
    return (
        <table className="workout-table">
            <thead>
                <tr>
                    <th>Hareket</th>
                    <th></th>
                </tr>
            </thead>

            <tbody>
                {selectedList.map((item) => (
                    <tr key={item.Id}>
                        <td>
                            <div className="cell-container">
                                <select
                                    value={item.ExerciseId ?? ""}
                                    onChange={(e) => handleChange(item.Id, "ExerciseId", e.target.value)}
                                >
                                    <option value="">Seçiniz</option>
                                    {exercises.map((ex) => (
                                        <option key={ex.Id} value={ex.Id?.toString()}>
                                            {ex.Name}
                                        </option>
                                    ))}
                                </select>

                                {item.ExerciseId !== "" && (
                                    <button className="delete-btn" onClick={() => removeItem(item.Id || 0)}>
                                        Sil
                                    </button>
                                )}
                            </div>
                        </td>
                    </tr>
                ))}
            </tbody>
        </table>
    );
};

export default WorkoutTable;
