import { useEffect, useState } from "react";
import { useActivityApiHooks } from "./ActivityApiHooks";
import { useSelector } from 'react-redux';
import { RootState } from '../../store';
import { toastError, toastSuccess } from "../../helpers/toast";
import { Exercise } from "../Workout/WorkoutViewModal";
import { ApiResponse, post } from "../../helpers/apiHelper";

interface ExerciseRow {
    Id: number;
    ExerciseName: string;
    Description: string;
    IsCardio: number;
    Reps: number;
    Sets: number;
    DurationOrWeight: number;
}

const Activity = () => {
    const { getWorkoutDataId, fetchWorkoutExercises } = useActivityApiHooks();
    const userId = useSelector((s: RootState) => s.auth.id);
    const path = window.location.pathname;
    const workoutId = Number(path.split("/")[2]);
    const date = (path.split("/")[3]);
    const [exercises, setExercises] = useState<ExerciseRow[]>([]);
    const [workoutDataId, setWorkoutDataId] = useState<number>(0);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!workoutId || !userId) return;

        const run = async () => {
            setLoading(true);

            const workoutDataId = await getWorkoutDataId(workoutId, userId, date);
            if (workoutDataId == 0) {
                toastError('Kendi Harektine Bak kardeşim.');
                window.location.href = '/';
                return false;
            }
            setWorkoutDataId(workoutDataId);

            toastSuccess('İyi Basmalar Kardeşşşşşşşş');

            const data: Exercise[] = (await fetchWorkoutExercises(workoutId)) || [];
            const initialExercises: ExerciseRow[] = data.map(e => ({
                Id: e.Id,
                ExerciseName: e.ExerciseName,
                Description: e.Description,
                IsCardio: e.IsCardio,
                Reps: 0,
                Sets: 0,
                DurationOrWeight: 0,
            }));

            setExercises(initialExercises);
            setLoading(false);
            return true;
        };

        const runAll = async () => {
            const result = await run();
        };

        runAll();
    }, [workoutId, userId, getWorkoutDataId, fetchWorkoutExercises]);

    const handleChange = <K extends keyof ExerciseRow>(index: number, field: K, value: ExerciseRow[K]) => {

        setExercises(prev => {
            const updated = [...prev];
            updated[index][field] = value;
            return updated;
        });
    };

    const handleSave = async () => {
        setLoading(true);
        try {
            const payload = {
                WorkoutDataId: workoutDataId,
                Sets: exercises.map(ex => ({
                    Exercise_Id: ex.Id,
                    Reps: ex.Reps ?? null,
                    Set_Number: ex.Sets ?? null,
                    Weight: ex.IsCardio ? null : ex.DurationOrWeight ?? null,
                    Minute: ex.IsCardio ? ex.DurationOrWeight ?? null : null,
                }))
            };
            const result: ApiResponse<null> = await post('addworkoutdatasets.php', payload);
            if (result.isSuccess) {
                toastSuccess('Data Başarılı şekilde kaydedildi');
                return true;
            } else {
                toastError(result.errorMessage || ' Bilgiler kaydedilemedi');
                return false;
            }
        } catch (err: any) {
            const msg = err?.data?.message || err?.message || ' Bilgiler kaydedilemedi';
            toastError(msg);
            return false;
        } finally {
            setLoading(false);
        }
    };
    if (loading) {
        return <main><h1>Loading...</h1></main>;
    }

    return (
        <main>
            <h1>Activity</h1>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                    <tr>
                        <th style={{ border: "1px solid #ccc", padding: "8px" }}>Exercise Name</th>
                        <th style={{ border: "1px solid #ccc", padding: "8px" }}>Description</th>
                        <th style={{ border: "1px solid #ccc", padding: "8px" }}>Tekrar</th>
                        <th style={{ border: "1px solid #ccc", padding: "8px" }}>Set</th>
                        <th style={{ border: "1px solid #ccc", padding: "8px" }}>Ağırlık / Dakika</th>
                    </tr>
                </thead>
                <tbody>
                    {exercises.map((ex, i) => (
                        <tr key={ex.Id}>
                            <td style={{ border: "1px solid #ccc", padding: "8px" }}>{ex.ExerciseName}</td>
                            <td style={{ border: "1px solid #ccc", padding: "8px" }}>{ex.Description}</td>
                            <td style={{ border: "1px solid #ccc", padding: "8px" }}>
                                <input
                                    type="number"
                                    value={ex.Reps}
                                    onChange={(e) => handleChange(i, "Reps", Math.max(0, Number(e.target.value)))}
                                />
                            </td>
                            <td style={{ border: "1px solid #ccc", padding: "8px" }}>
                                <input
                                    type="number"
                                    value={ex.Sets}
                                    onChange={(e) => handleChange(i, "Sets", Math.max(0, Number(e.target.value)))}
                                />
                            </td>
                            <td style={{ border: "1px solid #ccc", padding: "8px" }}>
                                <input
                                    type="number"
                                    value={ex.DurationOrWeight}
                                    onChange={(e) => handleChange(i, "DurationOrWeight", Math.max(0, Number(e.target.value)))}
                                />
                                <span style={{ marginLeft: "4px" }}>{ex.IsCardio ? "Dakika" : "Ağırlık"}</span>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>

            <button onClick={handleSave} style={{ marginTop: "10px", padding: "8px 16px" }}>Save</button>
        </main>
    );
};

export default Activity;
